/* ─────────────────────────────────────────────────
   CONTACT FORM
───────────────────────────────────────────────── */
function ContactForm() {
  const [fields, setFields] = useState({ name: '', email: '', message: '' })
  const [errors, setErrors] = useState({ name: '', email: '', message: '' })
  const [status, setStatus] = useState<'idle' | 'sending' | 'ok' | 'err'>('idle')

  const validate = () => {
    const e = { name: '', email: '', message: '' }
    if (!fields.name.trim()) e.name = 'Required'
    if (!fields.email.trim()) e.email = 'Required'
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email)) e.email = 'Invalid email'
    if (!fields.message.trim()) e.message = 'Required'
    setErrors(e)
    return !e.name && !e.email && !e.message
  }

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!validate()) return
    setStatus('sending')
    try {
      const res = await fetch('/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({ 'form-name': 'contact', ...fields }).toString(),
      })
      setStatus(res.ok ? 'ok' : 'err')
      if (res.ok) setFields({ name: '', email: '', message: '' })
    } catch { setStatus('err') }
  }

  const inputBase: React.CSSProperties = {
    background: 'transparent',
    border: 'none',
    borderBottom: '1px solid rgba(14,12,10,0.15)',
    padding: '0.75rem 0',
    fontFamily: 'Inter, sans-serif',
    fontSize: '0.9375rem',
    fontWeight: 300,
    color: '#0e0c0a',
    width: '100%',
    outline: 'none',
    borderRadius: 0,
    WebkitAppearance: 'none',
  }

  return (
    <form name="contact" method="POST" data-netlify="true" onSubmit={submit} noValidate
      style={{ display: 'flex', flexDirection: 'column', gap: '2.5rem' }}>
      <input type="hidden" name="form-name" value="contact" />

      {(['name', 'email', 'message'] as const).map(f => (
        <div key={f}>
          <label style={{
            display: 'block',
            fontSize: '0.5625rem',
            fontWeight: 500,
            letterSpacing: '0.2em',
            textTransform: 'uppercase',
            color: 'rgba(14,12,10,0.38)',
            marginBottom: '0.5rem',
          }}>{f.charAt(0).toUpperCase() + f.slice(1)}</label>
          {f === 'message'
            ? <textarea value={fields.message} rows={4}
              onChange={e => setFields(p => ({ ...p, message: e.target.value }))}
              onFocus={e => (e.target.style.borderBottomColor = '#c9a227')}
              onBlur={e => (e.target.style.borderBottomColor = 'rgba(14,12,10,0.15)')}
              style={{ ...inputBase, resize: 'none', minHeight: 100 }} />
            : <input type={f === 'email' ? 'email' : 'text'} value={fields[f]}
              onChange={e => setFields(p => ({ ...p, [f]: e.target.value }))}
              onFocus={e => (e.target.style.borderBottomColor = '#c9a227')}
              onBlur={e => (e.target.style.borderBottomColor = 'rgba(14,12,10,0.15)')}
              style={inputBase} />
          }
          {errors[f] && <span style={{ fontSize: '0.6875rem', color: '#c0634e', display: 'block', marginTop: '0.375rem' }}>{errors[f]}</span>}
        </div>
      ))}

      <button type="submit" disabled={status === 'sending'} data-hover="true"
        style={{
          alignSelf: 'flex-start',
          fontFamily: 'Inter, sans-serif',
          fontSize: '0.6875rem',
          fontWeight: 500,
          letterSpacing: '0.18em',
          textTransform: 'uppercase',
          color: '#0a0a0a',
          background: '#c9a227',
          border: '1px solid #c9a227',
          padding: '1em 2.5em',
          transition: 'background 0.3s, color 0.3s',
          opacity: status === 'sending' ? 0.65 : 1,
        }}
        onMouseEnter={e => { const b = e.currentTarget; b.style.background = 'transparent'; b.style.color = '#c9a227' }}
        onMouseLeave={e => { const b = e.currentTarget; b.style.background = '#c9a227'; b.style.color = '#0a0a0a' }}>
        {status === 'sending' ? 'Sending…' : 'Send'}
      </button>

      {status === 'ok' && <p style={{ fontSize: '0.8125rem', color: '#6faa72', fontStyle: 'italic', fontFamily: "'Fraunces', serif" }}>Received. I'll be in touch.</p>}
      {status === 'err' && <p style={{ fontSize: '0.8125rem', color: '#c0634e' }}>Something went wrong — email <a href="mailto:yogolsachin@gmail.com" style={{ color: '#c9a227', textDecoration: 'underline' }}>hello@sachinyagol.com</a> directly.</p>}
    </form>
  )
}

